/**
 * The canonical event vocabulary for one streamed agent turn — the wire
 * contract between a chat server and any client rendering it.
 *
 * The TSDoc on each variant is normative: it states what a conforming client
 * MUST render and how the user's interaction feeds back into the next turn.
 * See the README for the full rendering contract.
 */

import type { QuestionSpec } from "./question";
import type { ControlsSpec } from "./controls";
import type { ViewComponent, ViewSpec } from "./view";

/**
 * Version of this event contract. Servers include it on `session_started` so
 * clients replaying buffered events across a deploy can detect skew.
 */
export const PROTOCOL_VERSION = 13;

/** A small provider-normalized value shown inside an expanded tool-call row,
 * e.g. `{ label: "Command", value: "bun test" }`. */
export interface ToolCallDetail {
  label: string;
  value: string;
}

/** Provider-normalized task identity carried by task-management tool calls.
 * It lets clients correlate a later TaskUpdate with its earlier TaskCreate. */
export interface ToolTaskMetadata {
  id?: string;
  subject?: string;
  status?: string;
}

/** One provider-normalized step from a Codex plan/todo snapshot. */
export interface ToolPlanItem {
  text: string;
  status: string;
}

export type BackgroundAgentStatus =
  | "pending"
  | "running"
  | "completed"
  | "failed"
  | "interrupted";

export interface BackgroundAgentProgress {
  totalTokens?: number;
  toolUses?: number;
  durationMs?: number;
  lastToolName?: string;
}

/** A complete, replace-in-place snapshot of one provider background agent. */
export interface BackgroundAgent {
  id: string;
  provider: "claude" | "codex";
  parentToolCallId?: string;
  description?: string;
  agentType?: string;
  status: BackgroundAgentStatus;
  summary?: string;
  error?: string;
  progress?: BackgroundAgentProgress;
  /** Unix epoch timestamp in milliseconds, captured by the runner clock. */
  startedAt: number;
  /** Unix epoch timestamp in milliseconds for this snapshot. */
  updatedAt: number;
  /** Unix epoch timestamp in milliseconds when the agent reached a terminal state. */
  endedAt?: number;
}

/** Where one MCP server stands, normalized across providers. */
export interface McpServerStatus {
  name: string;
  status: "connecting" | "connected" | "failed" | "needs-auth" | "disabled";
  /** Why it failed, when the provider says. */
  error?: string;
}

/** An MCP server asking the user for something while its tool call waits. The
 * host mints `id`; the client quotes it when answering through the host's own
 * API. */
export type McpElicitation = { id: string; serverName: string; message: string } & (
  | { mode: "form"; requestedSchema: Record<string, unknown> }
  | { mode: "url"; url: string }
);

export type McpElicitationAction = "accept" | "decline" | "cancel";

/** A file the user sent with a message, as the host stores it. `id` names it
 * to the host's attachment route; the bytes never ride the stream. */
export interface AttachmentRef {
  id: string;
  name: string;
  mimeType: string;
  /** Bytes. */
  size: number;
}

/** Words the user sent that wait on the host: a `steer` for the running turn
 * the agent hasn't taken yet, or a `queue`d message to run as a turn of its
 * own once the thread is free. `id` is the id the sending client minted. */
export interface PendingMessage {
  id: string;
  kind: "steer" | "queue";
  text: string;
  /** The app-defined chat mode it was sent in. */
  mode: string;
  /** Unix milliseconds the host took it. */
  ts: number;
  /** Another thread's agent sent it; on another of the host's machines when
   * `machineId` is given. */
  from?: { threadId: string; title: string; machineId?: string; machineName?: string };
  /** Files sent with it; absent when none. */
  attachments?: AttachmentRef[];
}

/** One compaction attempt's step: it began, it replaced the history with a summary, or it gave up and left the history as it was. */
export type CompactionPhase = "started" | "finished" | "failed";

/** `manual` when the user asked for the compaction, `auto` when the agent CLI decided on it. */
export type CompactionTrigger = "manual" | "auto";

/** Why a turn ended without completing. `user` is a deliberate cancel;
 * `timeout` is the runner's wall-clock limit. Render them differently. */
export type AbortReason = "user" | "timeout";

export type ChatStreamEvent =
  /**
   * The turn is running under this session/thread id. Emitted once near the
   * start of a first turn. Clients persist the id and send it back on the next
   * turn to continue the conversation; a second occurrence with a different id
   * supersedes the first. Not emitted on resumed turns — the client already
   * holds the id it resumed with.
   */
  | {
      type: "session_started";
      sessionId: string;
      /** Contract version the server speaks; see {@link PROTOCOL_VERSION}. */
      protocolVersion?: number;
    }
  /**
   * A completed assistant message. Clients MUST render it as GitHub-flavored
   * markdown (sanitized). Multiple occurrences in one turn are separate
   * messages, in order — not fragments to concatenate.
   */
  | { type: "assistant_text"; text: string }
  /**
   * A fragment of the assistant message still being written. `index` counts
   * assistant messages within the turn from 0, so fragments belong to the
   * message the next `assistant_text` will deliver.
   *
   * Clients MUST append `delta` to a scratch buffer for `index` and MAY render
   * that buffer as in-progress prose, and MUST discard the buffer when the
   * `assistant_text` for the same index arrives — that event is the transcript
   * message, and the buffer is never one. Fragments are best-effort: they are
   * not persisted, they stop at a generative-UI block (whose rendered card
   * would otherwise be preceded by its raw markup), and a turn may deliver an
   * `assistant_text` with no preceding fragments at all.
   */
  | { type: "assistant_text_delta"; index: number; delta: string }
  /**
   * The agent invoked a tool. Clients MUST show at least `name` inline in the
   * transcript and preserve every event in stream order relative to assistant
   * text. `summary` is an optional concise description; `details` are optional
   * curated label/value metadata. Neither carries tool output — this is a trace
   * of what ran, not results. Grouping and expansion layout are non-normative
   * client presentation choices; see the README guidance.
   */
  | {
      type: "tool_use";
      name: string;
      summary?: string;
      details?: ToolCallDetail[];
      task?: ToolTaskMetadata;
      plan?: ToolPlanItem[];
    }
  /**
   * A structured clarifying question. Clients MUST render the options as
   * selectable choices; the chosen option's label (or a typed free-text reply)
   * is sent verbatim as the next user turn. Selecting locally marks the card
   * answered — no special reply channel exists.
   *
   * With `questions` the card is a form: clients SHOULD render every question,
   * take several picks where `multi` is set and a typed answer for any of
   * them, and send all the answers at once as one user turn, formatted by
   * `formatQuestionAnswers`. A client that ignores `questions` still has the
   * first question in `question` and `options`.
   */
  | ({ type: "question" } & QuestionSpec)
  /**
   * A proposed implementation plan (a `<proposed_plan>` block body) from a
   * plan-mode turn. Clients MUST render `planMarkdown` as sanitized
   * GitHub-flavored markdown (like `assistant_text` — it is agent output,
   * so unsafe raw HTML and URL schemes must not reach the DOM), SHOULD
   * present it as a distinct plan card (`title` is the plan's first heading,
   * for compact headers), and SHOULD offer the round-trip the emitting
   * prompt promises the agent: user feedback refines the plan in a further
   * plan-mode turn, and an approval sends the plan text back verbatim as an
   * implement request outside plan mode. The plan is transcript content
   * alongside `assistant_text`.
   */
  | { type: "plan"; planMarkdown: string; title: string | null }
  /**
   * A live parameter panel. Clients MUST render each control as an input
   * seeded with its `value`, and on Apply send an app-defined message
   * composed from the final values as the next user turn. Apps may extend
   * the spec with extra fields via their own validators (carve layers CSS
   * style bindings this way); a client that doesn't understand an extension
   * renders the widgets + Apply round-trip and ignores the rest. A panel is
   * retired by the next user message.
   */
  | { type: "controls"; spec: ControlsSpec }
  /**
   * A generative-UI view composed from the shared component catalog.
   * Clients MUST render known components natively in graph order, skip
   * unknown or invalid ones (the rest of the view still renders), and treat
   * the event as a transcript message alongside `assistant_text`. Inputs
   * bind view-local $vars; a Button's `message` template — `{$var}` tokens
   * interpolated from those values — is sent verbatim as the next user turn,
   * and `href` Buttons open externally. Views are static content otherwise:
   * no handlers, no expressions, no executable payloads.
   */
  | { type: "view"; spec: ViewSpec }
  /**
   * One validated component of a view still being written, in stream order.
   * `index` counts assistant messages within the turn, matching
   * `assistant_text_delta`. Clients MAY hydrate a skeleton view from these
   * fragments and MUST discard them when the completed `view` (or the
   * message's `assistant_text`) arrives — that event is authoritative and
   * runs full graph validation, which per-line delivery cannot. Like text
   * fragments they are best-effort scratch state: never persisted, never
   * counted as replayed messages, and a view may arrive with no preceding
   * lines at all.
   */
  | { type: "view_line"; index: number; component: ViewComponent }
  /**
   * A freeform generated page (an ```agent-html``` block body). Clients MUST
   * render it in a sandboxed frame wired to the bridge protocol in html.ts —
   * never inline in the app document — and treat the event as a transcript
   * message alongside `assistant_text`. The frame's `agent-html:send`
   * messages are sent verbatim as the next user turn.
   */
  | { type: "html"; content: string }
  /**
   * A newline-terminated run of completed lines from an html block still
   * being written. `index` counts assistant messages within the turn,
   * matching `assistant_text_delta`. Clients MAY append deltas to a scratch
   * document and render it as a growing page, and MUST discard the scratch
   * when the completed `html` (or the message's `assistant_text`) arrives —
   * that event is authoritative. Like text fragments they are best-effort
   * scratch state: never persisted, and a page may arrive with no preceding
   * deltas at all.
   */
  | { type: "html_delta"; index: number; delta: string }
  /**
   * A context-window usage snapshot for the turn. Non-terminal and may arrive
   * more than once (each supersedes the last); clients render the latest as a
   * context meter. `contextWindow` is absent when the provider reported no
   * window and none could be resolved — show `contextTokens` without a
   * percentage in that case. Counts are provider-reported and may be
   * approximate; clamp the meter at 100% rather than treating overflow as an
   * error.
   */
  | {
      type: "context_usage";
      /** Tokens occupying the context window, per the provider's best report. */
      contextTokens: number;
      /** Total window size in tokens, when known. */
      contextWindow?: number;
      /** Model that produced the usage, when known. */
      model?: string;
    }
  /**
   * The agent CLI is compacting the conversation: replacing its history with a summary so the context window has room again. Non-terminal and replayable, and not transcript content. Each attempt has an `id` and arrives as `started`, then `finished` or `failed` under the same id; a turn that ends first ends the attempt too, so clients MUST close an attempt still open at the turn's terminal event. A `finished` or `failed` may arrive with no `started` before it. Clients MAY show an open attempt as in progress, and SHOULD treat the size on `started` as the context before compacting: the size after it arrives as a later `context_usage`.
   */
  | {
      type: "compaction";
      /** One attempt, unique within the turn ("compaction-1", …). */
      id: string;
      phase: CompactionPhase;
      trigger: CompactionTrigger;
      /** started only: the context as last measured before compacting. */
      contextTokens?: number;
      contextWindow?: number;
      /** failed only: the agent CLI's reason, when it gave one. */
      error?: string;
    }
  /**
   * The canonical title state for the chat containing this turn. Non-terminal
   * and emitted when an asynchronous title generator answers. Clients MUST
   * update the chat/thread title without adding a transcript message.
   *
   * Each task field is a tri-state statement: a string stores that value, an
   * explicit `null` clears the stored one, and an absent field says nothing —
   * the client keeps whatever it has. The fields are opaque to the client: it
   * stores them and returns them on the next turn's title request, which is
   * what lets the generator track an umbrella objective across a conversation
   * instead of renaming from the latest message alone.
   *
   * Who keeps that state decides how a server emits. A server whose client
   * owns the chat (browser-held history) MUST emit a complete snapshot on
   * every model answer — both task fields present, a dropped one stated as
   * `null` ({@link threadTitleSnapshotEvent} builds this) — including an
   * answer that keeps the title and only refreshes the task summary;
   * withholding it strands the client a turn behind. A server that persists
   * the state itself MAY emit only when the title changes and leave the task
   * fields absent. Either way clients MUST apply a repeated `title`
   * idempotently.
   */
  | {
      type: "thread_title";
      title: string;
      /** Durable summary of the conversation's umbrella objective: a string
       * stores it, `null` clears it, absent leaves the stored value alone. */
      overarchingTask?: string | null;
      /** Unrelated task seen once, pending confirmation before it retitles;
       * same tri-state semantics. */
      pivotCandidate?: string | null;
    }
  /**
   * A full background-agent lifecycle snapshot. Non-terminal and mutable:
   * clients MUST upsert by `agent.id`, replacing the prior snapshot instead
   * of appending a transcript message for every progress event. Status is one
   * of `pending`, `running`, `completed`, `failed`, or `interrupted`; provider
   * ids, spawn correlation, progress, summaries, errors, and Unix-millisecond
   * timestamps remain available on the snapshot.
   */
  | { type: "background_agent_updated"; agent: BackgroundAgent }
  /**
   * Every MCP server's status, as a complete snapshot that replaces the last.
   * Non-terminal and replayable, and not transcript content: clients MAY show
   * it, and MUST NOT add a transcript message for it.
   */
  | { type: "mcp_status"; servers: McpServerStatus[] }
  /**
   * An MCP server needs the user's input, and its tool call is waiting. Non-
   * terminal and replayable, and not transcript content. A client that supports
   * it renders the request and answers through the host's API; it stays open
   * until a matching `mcp_elicitation_resolved` or the end of the turn. A client
   * that doesn't MAY ignore it, in which case the host's timeout ends the wait.
   * Render `url` only with the user's consent, showing its host: the server
   * chose it. The answer itself never appears in the stream.
   */
  | { type: "mcp_elicitation"; request: McpElicitation }
  /** The request `id` is over, however it ended. Clients MUST retire it. */
  | { type: "mcp_elicitation_resolved"; id: string; action: McpElicitationAction }
  /**
   * Everything the user sent that still waits on the host, as a complete
   * snapshot that replaces the last: steers the agent hasn't taken and messages
   * queued to run after the turn. `revision` only ever rises for a thread, so a
   * client can ignore an older list it reads later. Non-terminal and
   * replayable, and not transcript content: a steer that lands still arrives as
   * its own `user_message`.
   */
  | { type: "pending_messages"; revision: number; messages: PendingMessage[] }
  /**
   * The user steered the running turn: words typed while the agent worked,
   * handed to it mid-turn. Non-terminal and replayable. Clients MUST render
   * `text` as a user message at this point in the stream — between the agent
   * output before it and after it — and MUST NOT start a new turn for it.
   * `steerId` is the id the sending client minted, so it can retire its own
   * optimistic copy; `turnId` names the turn steered and `mode` the chat mode
   * the turn runs in (an app-defined string). A steer may carry files, and
   * then `text` may be blank.
   */
  | {
      type: "user_message";
      text: string;
      steerId: string;
      turnId: string;
      mode: string;
      /** Unix milliseconds the agent took the message. */
      ts: number;
      /** Files sent with the steer; absent when none. */
      attachments?: AttachmentRef[];
    }
  /**
   * Raw stderr from the agent CLI. Diagnostic channel — clients MAY ignore it
   * or surface it in a collapsed log. Never render it as assistant prose.
   */
  | { type: "stderr"; chunk: string }
  /** Terminal: the turn completed. `exitCode` 0 is success. */
  | { type: "done"; exitCode: number }
  /** Terminal: the turn was killed before completing. See {@link AbortReason};
   * absent means an unspecified abort (treat as `user`). */
  | { type: "aborted"; reason?: AbortReason }
  /** Terminal: the turn failed. `message` is human-readable and safe to show. */
  | { type: "error"; message: string };

/** True for the three events that end a turn's stream: `done`, `aborted`,
 * `error`. After one of these, no further events arrive for the turn. */
export function isTerminalEvent(ev: ChatStreamEvent): boolean {
  return ev.type === "done" || ev.type === "aborted" || ev.type === "error";
}

/** The `thread_title` member of {@link ChatStreamEvent}, named for hosts that
 * build, store, or apply title state. */
export type ThreadTitleEvent = Extract<ChatStreamEvent, { type: "thread_title" }>;

/** Title state as a generator or host holds it, before it becomes an event. */
type ThreadTitleState = {
  title: string;
  overarchingTask?: string | null | undefined;
  pivotCandidate?: string | null | undefined;
};

/**
 * Builds a sparse `thread_title` event: a non-empty string is stated, an
 * explicit `null` clears, and an empty or missing field is left off the event
 * — no statement, the client keeps what it has. Right for a server that
 * persists title state itself and only announces renames. A server whose
 * client owns the state needs {@link threadTitleSnapshotEvent} instead: a
 * sparse event would strand a dropped field on the client forever.
 */
export function threadTitleEvent(state: ThreadTitleState): ThreadTitleEvent {
  return {
    type: "thread_title",
    title: state.title,
    ...(state.overarchingTask || state.overarchingTask === null
      ? { overarchingTask: state.overarchingTask }
      : {}),
    ...(state.pivotCandidate || state.pivotCandidate === null
      ? { pivotCandidate: state.pivotCandidate }
      : {}),
  };
}

/**
 * Builds the complete `thread_title` snapshot a server MUST emit when its
 * client owns the title state: both task fields are always present, a dropped
 * or empty one stated as an explicit `null` so the client clears it. Accepts
 * a `ChatTitleResult` directly.
 */
export function threadTitleSnapshotEvent(state: ThreadTitleState): ThreadTitleEvent {
  return {
    type: "thread_title",
    title: state.title,
    overarchingTask: state.overarchingTask || null,
    pivotCandidate: state.pivotCandidate || null,
  };
}
